<template><section class="photo-history"><h3>이전 프로필 사진</h3><p>교체·삭제 후 90일 보관 · 탈퇴 시 삭제. 얼굴 비교용 압축본입니다.</p><button type="button" :disabled="busy" @click="load">{{busy?'불러오는 중…':'사진 이력 보기 / 새로고침'}}</button><p v-if="loaded&&!rows.length">보관 중인 이전 사진이 없습니다.</p><div class="history-grid"><figure v-for="row in rows" :key="row.id"><img tabindex="0" role="button" title="사진 확대" style="cursor:zoom-in" v-if="urls[row.id]" :src="urls[row.id]" alt="이전 프로필 사진"/><figcaption>{{row.reason==='DELETED'?'삭제':'교체'}} · {{date(row.archivedAt)}}<br/>보관 종료 {{date(row.expiresAt)}} · {{Math.ceil(row.bytes/1024)}}KB</figcaption></figure></div><div v-if="loaded"><button :disabled="busy||page===0" @click="page--;load()">이전</button><span>{{page+1}}</span><button :disabled="busy||rows.length<20" @click="page++;load()">다음</button></div><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup>
import {ref,watch,onUnmounted} from 'vue';import api from '../api/api';const props=defineProps({userId:Number,active:Boolean});const rows=ref([]),urls=ref({}),busy=ref(false),error=ref(''),loaded=ref(false),page=ref(0);let epoch=0;
const date=v=>new Date(v).toLocaleDateString('ko-KR');function release(){epoch++;Object.values(urls.value).forEach(URL.revokeObjectURL);urls.value={};rows.value=[];}
async function load(){release();if(!props.active)return;busy.value=true;error.value='';const current=epoch;try{const list=(await api.get(`/admin/photo-history/user/${props.userId}`,{params:{page:page.value}})).data;if(current!==epoch)return;rows.value=list;loaded.value=true;for(const row of list){const p=await api.get(`/admin/photo-history/${row.id}/photo`,{responseType:'blob'});if(current!==epoch)return;urls.value[row.id]=URL.createObjectURL(p.data);}}catch{if(current===epoch)error.value='사진 이력을 불러오지 못했습니다.';}finally{if(current===epoch)busy.value=false;}}
watch(()=>[props.userId,props.active],()=>{release();loaded.value=false;busy.value=false;page.value=0;error.value='';});onUnmounted(release);
</script><style scoped>.photo-history{padding:18px;border:1px solid #e7ddd5;border-radius:14px;margin:18px 0}.photo-history p,figcaption{font-size:12px;line-height:1.7;color:#75685f}.history-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;margin:16px 0}figure{margin:0}img{width:100%;height:180px;object-fit:contain;background:#eee;border-radius:10px}button{padding:9px 12px;background:#eee1d8;border:0;border-radius:9px;cursor:pointer}button:disabled{opacity:.5}[role=alert]{color:#a33}</style>